import "fmt"

const (
	Read  = 1 << iota // 1 (iota 0)
	Write             // 2 (iota 1)
	Exec              // 4 (iota 2)
)

func main() {
	perm := Read | Write           // 1 | 2 == 3
	fmt.Println(perm&Write != 0)   // true: bit 2 is set
	fmt.Println(perm&Exec != 0)    // false: bit 4 not set
}

