import "fmt"

const (
	_  = iota             // skip iota 0
	KB = 1 << (10 * iota) // 1<<10 = 1024
	MB                    // 1<<20
	GB                    // 1<<30
)

func Human(n int64) string {
	switch {
	case n >= GB:
		return fmt.Sprintf("%dGB", n/GB)
	case n >= MB:
		return fmt.Sprintf("%dMB", n/MB)
	case n >= KB:
		return fmt.Sprintf("%dKB", n/KB)
	default:
		return fmt.Sprintf("%dB", n)
	}
}

const (
	Read  = 1 << iota // 1 (iota 0)
	Write             // 2 (iota 1)
	Exec              // 4 (iota 2)
)

// Can reports whether perm includes ALL bits set in want.
func Can(perm, want int) bool {
	return perm&want == want
}
